function findSelect(systemFile) {
  const root = gameRoot(systemFile);
  const candidates = [root && path.join(root, 'data', 'select.def'), path.join(path.dirname(systemFile), 'select.def')].filter(Boolean);
  return candidates.find((item) => fs.existsSync(item)) || null;
}

async function resolveFiles(uri) {
  let systemFile = uri?.fsPath;
  if (systemFile && path.basename(systemFile).toLowerCase() === 'select.def') systemFile = await locateCharacterSelectMotif(uri);
  if (systemFile && /\.def$/i.test(systemFile)) {
    try { if (kind(parseDef(fs.readFileSync(systemFile, 'utf8'), systemFile)) !== 'screenpack') systemFile = null; } catch (_) { systemFile = null; }
  }
  if (!systemFile) systemFile = await locateCharacterSelectMotif(uri || vscode.window.activeTextEditor?.document.uri);
  if (!systemFile) {
    systemFile = await chooseFileOrFolder({ title: 'Choose Screenpack for Menu and Modes', filters: { 'IKEMEN screenpack': ['def'] }, extensions: ['def'], predicate: (candidate) => kind(parseDef(fs.readFileSync(candidate, 'utf8'), candidate)) === 'screenpack', maxDepth: 4, invalidMessage: 'That DEF is not a screenpack system definition.', emptyMessage: 'No screenpack system DEF was found in that folder.' });
  }
  if (!systemFile) return null;
  let selectFile = findSelect(systemFile);
  if (!selectFile) {
    selectFile = await chooseFileOrFolder({ title: 'Choose Matching select.def', filters: { 'IKEMEN roster': ['def'] }, extensions: ['def'], predicate: (candidate) => path.basename(candidate).toLowerCase() === 'select.def', maxDepth: 4, invalidMessage: 'Choose a select.def roster definition.', emptyMessage: 'No select.def was found in that folder.' });
  }
  return selectFile ? { systemFile, selectFile } : null;
}

const REFERENCE_KEYS = ['type','uri','sourceRole','section','recordKind','normalizedKey','rawSignatureSha','occurrence','matchCount'];
function validMenuModeReference(reference) {
  return exactObject(reference,REFERENCE_KEYS)&&reference.type==='menu-mode-record-v1'&&typeof reference.uri==='string'&&reference.uri.length>=1&&reference.uri.length<=4096&&['system','select'].includes(reference.sourceRole)&&((reference.sourceRole==='system'&&reference.section==='title info'&&reference.recordKind==='menu-item')||(reference.sourceRole==='select'&&reference.section==='options'&&reference.recordKind==='select-option'))&&typeof reference.normalizedKey==='string'&&reference.normalizedKey.length>=1&&reference.normalizedKey.length<=512&&reference.normalizedKey===reference.normalizedKey.trim().toLowerCase()&&/^[0-9a-f]{64}$/.test(reference.rawSignatureSha)&&Number.isInteger(reference.occurrence)&&reference.occurrence>=0&&reference.occurrence<=9999&&Number.isInteger(reference.matchCount)&&reference.matchCount>=1&&reference.matchCount<=10000&&reference.occurrence<reference.matchCount;
}
function menuModeRecords(systemDocument,selectDocument,model) {
  const rows=[];
  for(const item of model.menu||[])rows.push({document:systemDocument,sourceRole:'system',section:'title info',recordKind:'menu-item',key:item.key,line:item.line,label:item.label||item.key});
  for(const item of model.options||[])rows.push({document:selectDocument,sourceRole:'select',section:'options',recordKind:'select-option',key:item.name,line:item.line,label:item.name});
  const prepared=rows.filter(row=>Number.isInteger(row.line)&&row.line>=0&&row.line<row.document.lineCount).map(row=>{const normalizedKey=String(row.key).trim().toLowerCase(),raw=row.document.lineAt(row.line).text,signatureInput=JSON.stringify(['menu-mode-record-v1',row.sourceRole,row.section,row.recordKind,normalizedKey,raw]);return{...row,normalizedKey,rawSignatureSha:hash(signatureInput)};}).filter(row=>row.normalizedKey.length>=1&&row.normalizedKey.length<=512);
  return deepFreeze(prepared.map(row=>{const matches=prepared.filter(candidate=>candidate.document.uri.toString()===row.document.uri.toString()&&candidate.rawSignatureSha===row.rawSignatureSha);const occurrence=matches.indexOf(row),reference=deepFreeze({type:'menu-mode-record-v1',uri:row.document.uri.toString(),sourceRole:row.sourceRole,section:row.section,recordKind:row.recordKind,normalizedKey:row.normalizedKey,rawSignatureSha:row.rawSignatureSha,occurrence,matchCount:matches.length});return{sourceRole:row.sourceRole,label:row.label,key:row.key,line:row.line,reference};}));
}
function findMenuModeRecord(systemDocument,selectDocument,model,reference) {
  if(!validMenuModeReference(reference))return null;
  const records=menuModeRecords(systemDocument,selectDocument,model),matches=records.filter(record=>record.reference.uri===reference.uri&&record.reference.sourceRole===reference.sourceRole&&record.reference.section===reference.section&&record.reference.recordKind===reference.recordKind&&record.reference.normalizedKey===reference.normalizedKey&&record.reference.rawSignatureSha===reference.rawSignatureSha);
  if(matches.length!==reference.matchCount)return null;
  const found=matches[reference.occurrence];
  return found&&JSON.stringify(found.reference)===JSON.stringify(reference)?found:null;
}
function menuModesTabTarget(key,index,count){const size=Math.max(0,Number(count)||0),current=size?Math.max(0,Math.min(size-1,Number(index)||0)):0;if(!size)return-1;if(key==='Home')return 0;if(key==='End')return size-1;if(key==='ArrowRight'||key==='ArrowDown')return(current+1)%size;if(key==='ArrowLeft'||key==='ArrowUp')return(current-1+size)%size;return-1;}

async function loadModel(files) {
  const systemDocument = await vscode.workspace.openTextDocument(vscode.Uri.file(files.systemFile));
  const selectDocument = await vscode.workspace.openTextDocument(vscode.Uri.file(files.selectFile));
  const root = gameRoot(files.systemFile), mainLua = root && path.join(root, 'external', 'script', 'main.lua');
  const actions = mainLua && fs.existsSync(mainLua) ? installedActionIds(fs.readFileSync(mainLua, 'utf8')) : [];
  const model={ ...buildMenuModesModel(parseDef(systemDocument.getText(), files.systemFile), parseSelectDef(selectDocument.getText()), { ...files, verificationFile: mainLua || '' }, actions), sourceStates: { system: sourceState(systemDocument, path.basename(systemDocument.fileName)), select: sourceState(selectDocument, path.basename(selectDocument.fileName)) } };
  model.sourceRecords=menuModeRecords(systemDocument,selectDocument,model);
  const byRole=role=>model.sourceRecords.filter(record=>record.sourceRole===role);
  for(const item of model.menu||[])item.sourceSlot=byRole('system').findIndex(record=>record.line===item.line&&record.key===item.key);
  for(const item of model.options||[])item.sourceSlot=byRole('select').findIndex(record=>record.line===item.line&&record.key===item.name);
  return { systemDocument, selectDocument, model };
}

